<script setup lang="ts">
import {onMounted,ref} from 'vue'; import {listBases,createBase,listDocuments,uploadDocument} from '../api/client'
const bases=ref<any[]>([]), docs=ref<any[]>([]), selected=ref(''), name=ref(''), desc=ref(''), error=ref(''), loading=ref(false)
async function load(){bases.value=(await listBases()).items;if(!selected.value&&bases.value[0]) selected.value=bases.value[0].ID||bases.value[0].id; if(selected.value) docs.value=(await listDocuments(selected.value)).items}
async function create(){if(!name.value.trim())return; await createBase(name.value,desc.value);name.value='';desc.value='';await load()}
async function upload(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f||!selected.value)return;loading.value=true;error.value='';try{await uploadDocument(selected.value,f);await load()}catch(x:any){error.value=x.message}finally{loading.value=false}}
onMounted(load)
</script>
<template><section class="library"><div class="card"><h2>知识库</h2><p class="muted">创建本地知识库并管理资料。</p><div class="form"><input v-model="name" placeholder="知识库名称" maxlength="120"><input v-model="desc" placeholder="描述（可选）"><button @click="create">创建</button></div><div class="base-list"><button v-for="b in bases" :key="b.ID||b.id" class="base" :class="{chosen:selected===(b.ID||b.id)}" @click="selected=b.ID||b.id;load()">{{b.NAME||b.name}}</button></div></div><div class="card"><h2>资料</h2><p v-if="!selected" class="muted">先选择或创建知识库。</p><template v-else><label class="upload">{{loading?'处理中…':'上传 PDF、DOCX、TXT 或 Markdown'}}<input type="file" accept=".pdf,.docx,.txt,.md" @change="upload"></label><p v-if="error" class="error">{{error}}</p><ul class="docs"><li v-for="d in docs" :key="d.ID||d.id"><span>{{d.ORIGINAL_NAME||d.original_name}}</span><span class="tag">{{d.STATUS||d.status}}</span></li></ul></template></div></section></template>
